parameters.functionCode:
const received = $input.item.json;
const action = received.body ?? received;
const payload = action.payload ?? {};

const deviceId = payload.device_id ?? `${payload.device_type ?? 'device'}_${payload.location ?? 'unknown'}`;
const command = payload.action ?? 'unknown';
const language = (action.context?.language || action.language || 'fr').toLowerCase();

return {
  json: {
    action_id: action.action_id ?? 'unknown',
    user_id: action.user_id ?? 'unknown',
    intent: action.intent ?? 'control_iot',
    language,
    device_id: deviceId,
    device_type: payload.device_type ?? 'device',
    location: payload.location ?? '',
    command,
    mqtt_topic: `gob/actions/${deviceId}/command`,
    mqtt_payload: {
      action_id: action.action_id ?? 'unknown',
      device_id: deviceId,
      device_type: payload.device_type ?? 'device',
      command,
      location: payload.location ?? '',
      timestamp: Math.floor(Date.now() / 1000),
      source: 'n8n_workflow'
    }
  }
};

const j = $input.item.json;
const isSuccess = j.command !== 'unknown' && j.device_id !== 'unknown';
return {
  json: {
    ...j,
    status: isSuccess ? 'success' : 'failed',
    result: isSuccess ? {
      device_id: j.device_id,
      command: j.command,
      location: j.location
    } : null,
    error: isSuccess ? null : 'iot_command_invalid'
  }
};

const j = $input.item.json;
const onMap = { fr: 'allumee', en: 'turned on', ar: 'تم تشغيله' };
const offMap = { fr: 'eteinte', en: 'turned off', ar: 'تم إيقافه' };
let actionLabel = j.command;
if (j.command === 'turn_on') actionLabel = onMap[j.language] || onMap.fr;
if (j.command === 'turn_off') actionLabel = offMap[j.language] || offMap.fr;
const tpl = {
  fr: `La ${j.device_type} de ${j.location || 'la maison'} est ${actionLabel}.`,
  en: `The ${j.device_type} in ${j.location || 'home'} is ${actionLabel}.`,
  ar: `تم تنفيذ امر ${j.device_type} في ${j.location || 'المنزل'}.`
};
return { json: { ...j, voice_text: tpl[j.language] || tpl.fr } };

const j = $input.item.json;
const tpl = {
  fr: `La commande IoT n'a pas ete executee pour ${j.device_type} ${j.location || ''}.`,
  en: `IoT command failed for ${j.device_type} ${j.location || ''}.`,
  ar: `فشل تنفيذ امر ${j.device_type} ${j.location || ''}.`
};
return { json: { ...j, voice_text: tpl[j.language] || tpl.fr } };

const j = $input.item.json;
const base = $item(0).$node['Build IoT Result'].json;
const audioUrl = j.audio_url || j.body?.audio_url;

let voiceText = '';
try {
  voiceText = $item(0).$node['Build Voice Success'].json.voice_text || '';
} catch (e) {}
if (!voiceText) {
  try {
    voiceText = $item(0).$node['Build Voice Failure'].json.voice_text || '';
  } catch (e) {}
}

return {
  json: {
    ...base,
    audio_url: audioUrl,
    mqtt_voice_topic: 'gob/audio/tts/request',
    mqtt_voice_payload: {
      request_id: $execution.id,
      action_id: base.action_id,
      user_id: base.user_id,
      lang: base.language,
      text: voiceText,
      url: audioUrl,
      ts: Math.floor(Date.now() / 1000)
    }
  }
};
